        return None
    raw = data.get("krw")
    if not isinstance(raw, dict) or not raw:
        return None
    rates: dict[str, float] = {}
    for cur, value in raw.items():
        try:
            rates[str(cur).upper()] = float(value)
        except (TypeError, ValueError):
            continue
    if "USD" not in rates:
        return None
